private static String generateValueBasedOnMatchType(String text, MatchType matchType) {
        switch (matchType) {
            case PREFIX:
            case PREFIX_EQUALS_IGNORE_CASE:
            case ANYTHING_BUT_PREFIX:
                return '"' + text;
            case SUFFIX:
            case SUFFIX_EQUALS_IGNORE_CASE:
            case ANYTHING_BUT_SUFFIX:
                return text + '"';
            default:
                return '"' + text + '"';
        }
